/**
 * @distilled.cloud/clerk -- Clerk Backend and Platform API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models that
 * `scripts/convert.ts` converts from the OpenAPI descriptions. Everything else in this
 * folder is hand-written.
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as Clerk from "@distilled.cloud/clerk";
 *
 * const program = Clerk.Platform.getMe({});
 * const Live = Layer.mergeAll(
 *   FetchHttpClient.layer,
 *   Clerk.PlatformCredentialsFromEnv,
 *   Clerk.ClerkPlatformProtocol,
 * );
 * program.pipe(Effect.provide(Live), Effect.runPromise);
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  ClerkProtocol,
  ClerkPlatformProtocol,
  type ClerkOpError,
  type ClerkOpContext,
  type ClerkPlatformOpContext,
} from "./protocol.ts";
export { paginateCursor } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
export * from "./services/clerk.ts";
export * as Platform from "./services/platform.ts";
export {
  BadRequest,
  Conflict,
  Forbidden,
  NotFound,
  UnprocessableEntity,
} from "./services/clerk.ts";
